def parse_duration(s: str) -> int:
    total = 0
    i = 0
    n = len(s)

    while i < n:
        if not s[i].isdigit():
            raise ValueError(f"Invalid duration: {s!r}")
        start = i
        while i < n and s[i].isdigit():
            i += 1
        value = int(s[start:i])

        if i >= n or s[i] not in ('h', 'm', 's'):
            raise ValueError(f"Invalid duration: {s!r}")

        unit = s[i]
        i += 1

        if unit == 'h':
            total += value * 3600
        elif unit == 'm':
            total += value * 60
        else:
            total += value

    return total
```

